  [ex("Antes de bailar, ¿haces un calentamiento breve o empiezas sin preparar el cuerpo?", "Un calentamiento breve", "Prepara las articulaciones y evita lesiones."),
   ex("Tu piso está mojado y resbala. ¿Qué haces: A) bailas igual con cuidado, B) esperas a que se seque?", "B", "Un piso resbaloso aumenta el riesgo de caída."),
   ex("Una amiga dice que una danza de otra zona «es rara» y se ríe. ¿Qué respuesta es respetuosa: «Cada zona tiene sus bailes y merece respeto» o «Tienes razón»?", "Cada zona tiene sus bailes y merece respeto", "Respeta la identidad de cada zona.")],
