  [ex("Ema usa sandalias sueltas y se tropieza al bailar. Dani usa zapatos que se sujetan bien y baila sin problemas. ¿Quién eligió mejor su calzado?", "Dani", "Sus zapatos se sujetan, lo que previene caídas."),
   ex("Sofi dice: «La cueca solo se baila en Santiago». ¿Es correcto?", "No", "La cueca se baila en todo el país.")],
