  [arith("Una pareja baila 4 frases de 8 tiempos, descansa 8 tiempos y baila otras 2 frases de 8. ¿Cuántos tiempos bailó?", "4*8+2*8", "Se suman las frases bailadas sin contar el descanso.", " tiempos")],
