  [("paseo", "caminar con pasos suaves al ritmo de la música"), ("vuelta", "giro de la pareja en círculo"), ("zapateado", "golpes cortos de pie en el suelo"), ("escobillado", "deslizar la punta del pie rozando el suelo"), ("compás", "forma en que se agrupan los tiempos de la música")],
